    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof simulatorSettle>>, TError,SimulatorSettleMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof simulatorSettle>>, TError,SimulatorSettleMutationVariables, TContext> => {

const mutationKey = getSimulatorSettleMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof simulatorSettle>>, SimulatorSettleMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  simulatorSettle(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SimulatorSettleMutationResult = NonNullable<Awaited<ReturnType<typeof simulatorSettle>>>
    export type SimulatorSettleMutationBody = BodyType<SimulatorSettleInput>
    export type SimulatorSettleMutationError = ErrorType<ErrorResponseDto>
    export type SimulatorSettleMutationVariables = {data: BodyType<SimulatorSettleInput>}

    /**
 * @summary Liberar os saldos e rodar o repasse
 */
export const useSimulatorSettle = <TError = ErrorType<ErrorResponseDto>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof simulatorSettle>>, TError,SimulatorSettleMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof simulatorSettle>>,
        TError,
        SimulatorSettleMutationVariables,
        TContext
      > => {
      return useMutation(getSimulatorSettleMutationOptions(options), queryClient);
    }
